-- Title: Remote Thread Creation By Uncommon Source Image
-- ID: 66d31e5f-52d6-40a4-9615-002d3789a119
-- Status: test
-- Level: medium
-- Author: Perez Diego (@darkquassar), oscd.community
-- Date: 2019-10-27
-- Tags: attack.privilege-escalation, attack.stealth, attack.t1055
-- Description: Detects uncommon processes creating remote threads.
-- Converted by: Sigma Universal SIEM/EDR CLI

SELECT * FROM process_journal WHERE (((SourceImage ILIKE '%\\explorer.exe' OR SourceImage ILIKE '%\\iexplore.exe' OR SourceImage ILIKE '%\\msiexec.exe' OR SourceImage ILIKE '%\\powerpnt.exe' OR SourceImage ILIKE '%\\schtasks.exe' OR SourceImage ILIKE '%\\winlogon.exe')) AND NOT (((TargetImage = '') OR (SourceImage = 'C:\\Windows\\explorer.exe' AND (TargetImage ILIKE 'C:\\Program Files (x86)\\%' OR TargetImage ILIKE 'C:\\Program Files\\%' OR TargetImage ILIKE 'C:\\Windows\\System32\\%' OR TargetImage ILIKE 'C:\\Windows\\SysWOW64\\%')) OR (SourceImage = 'C:\\Program Files\\Internet Explorer\\iexplore.exe' AND (TargetImage = 'C:\\Program Files (x86)\\Internet Explorer\\iexplore.exe' OR TargetImage = 'C:\\Windows\\System32\\rundll32.exe')) OR (SourceImage ILIKE '%\\msiexec.exe' AND (TargetImage ILIKE '%\\AppData\\Local\\%' OR TargetImage ILIKE '%C:\\Program Files (x86)\\%' OR TargetImage ILIKE '%C:\\Program Files\\%' OR TargetImage ILIKE '%C:\\Windows\\Microsoft.NET\\Framework64\\%')) OR (SourceImage ILIKE '%\\msiexec.exe' AND (TargetImage = 'C:\\Windows\\System32\\msiexec.exe' OR TargetImage = 'C:\\Windows\\SysWOW64\\msiexec.exe')) OR (TargetImage IS NULL) OR (SourceImage ILIKE '%\\POWERPNT.EXE' AND (TargetImage ILIKE '%C:\\Program Files\\Microsoft Office\\%' OR TargetImage ILIKE '%C:\\Program Files (x86)\\Microsoft Office\\%')) OR ((SourceImage = 'C:\\Windows\\System32\\schtasks.exe' OR SourceImage = 'C:\\Windows\\SysWOW64\\schtasks.exe') AND TargetImage = 'C:\\Windows\\System32\\conhost.exe') OR (TargetImage = 'System') OR (SourceImage = 'C:\\Windows\\System32\\winlogon.exe' AND (TargetImage = 'C:\\Windows\\System32\\services.exe' OR TargetImage = 'C:\\Windows\\System32\\wininit.exe' OR TargetImage = 'C:\\Windows\\System32\\csrss.exe' OR TargetImage = 'C:\\Windows\\System32\\LogonUI.exe' OR TargetImage = 'C:\\Windows\\System32\\wlrmdr.exe' OR TargetImage = 'C:\\Windows\\System32\\AtBroker.exe' OR TargetImage = 'C:\\Windows\\System32\\dwm.exe' OR TargetImage = 'C:\\Windows\\System32\\fontdrvhost.exe' OR TargetImage = 'C:\\Windows\\System32\\userinit.exe')) OR (SourceImage = 'C:\\Windows\\System32\\winlogon.exe' AND TargetParentProcessId = 4))) AND NOT (((SourceImage = 'C:\\Windows\\explorer.exe' AND TargetImage ILIKE '%\\aurora-dashboard.exe') OR (SourceImage = 'C:\\Program Files\\internet explorer\\iexplore.exe' AND (SourceCommandLine ILIKE '%https://%' AND SourceCommandLine ILIKE '%.checkpoint.com/documents/%' AND SourceCommandLine ILIKE '%SmartConsole_OLH/%' AND SourceCommandLine ILIKE '%default.htm#cshid=%')) OR (SourceImage = 'C:\\Program Files\\internet explorer\\iexplore.exe' AND (SourceParentImage ILIKE 'C:\\Program Files\\%' OR SourceParentImage ILIKE 'C:\\Program Files (x86)\\%') AND (SourceParentImage ILIKE '%\\CheckPoint\\SmartConsole\\%' AND SourceParentImage ILIKE '%\\SmartConsole.exe%')) OR (SourceImage = 'C:\\Windows\\explorer.exe' AND TargetImage ILIKE '%\\OfficeSetup.exe') OR (SourceImage = 'C:\\Windows\\explorer.exe' AND TargetImage ILIKE '%\\AppData\\Local\\Microsoft\\OneDrive\\OneDrive.exe') OR (SourceImage ILIKE '%\\Microsoft Office\\%' AND SourceImage ILIKE '%\\POWERPNT.EXE' AND TargetImage = 'C:\\Windows\\System32\\csrss.exe'))))
